//! AdMob as a second revenue source (#94).
//!
//! Every constant here comes from `tools/fixtures/forepay-claim.json`, generated by
//! `tools/make_claim_fixture.py` and checked by CI. The AdMob identifier that generator
//! produces is **byte-identical** to the one `be/src/admob/fixture.test.ts` produces from
//! the relay's own request (#101) — a Python encoder and a TypeScript one agreeing on the
//! canonical parameters, the context and the keccak over them. That agreement is the
//! point of having a fixture at all, and it is what #102 taught: a harness that signs
//! what the contract expects proves only that the contract agrees with itself.

#![cfg(test)]

use super::*;
use soroban_sdk::{
    testutils::{Address as _, Ledger as _},
    Address, Bytes, Env, String, Vec,
};

use crate::test_claim::{
    signature_from, MockVerifier, APP_OWNER, BORROWER, EPOCH, PROVIDER_HASH, PUB_ID, REVENUE,
    TEMPLATE, TIMESTAMP_S, WINDOW_END, WINDOW_START,
};

/// The literal segments of the AdMob request, with the seven values interleaved.
///
/// Note where the values fall: the six date numbers are inside `body`, which sorts before
/// `url` in the canonical parameters, so `pub_id` is **last** rather than first (#93).
/// The separators end with escaped JSON keys (`\"month\":`) rather than with `=`.
const ADMOB_TEMPLATE: [&[u8]; 8] = [
    br#"{"body":"{\"reportSpec\":{\"dateRange\":{\"startDate\":{\"year\":"#,
    br#",\"month\":"#,
    br#",\"day\":"#,
    br#"},\"endDate\":{\"year\":"#,
    br#",\"month\":"#,
    br#",\"day\":"#,
    br#"}},\"metrics\":[\"ESTIMATED_EARNINGS\"],\"localizationSettings\":{\"currencyCode\":\"USD\"}}}","headers":{"User-Agent":"reclaim/0.0.1","accept":"application/json","content-type":"application/json"},"method":"POST","responseMatches":[{"type":"regex","value":"\"localizationSettings\":\\s*\\{\\s*\"currencyCode\":\\s*\"USD\"\\s*\\}"},{"type":"regex","value":"\"row\":\\s*\\{\\s*\"metricValues\":\\s*\\{\\s*\"ESTIMATED_EARNINGS\":\\s*\\{\\s*\"microsValue\":\\s*\"(?<revenueMicros>\\d+)\"\\s*\\}\\s*\\}\\s*\\}"}],"responseRedactions":[{"regex":"\"localizationSettings\":\\s*\\{\\s*\"currencyCode\":\\s*\"USD\"\\s*\\}"},{"regex":"\"row\":\\s*\\{\\s*\"metricValues\":\\s*\\{\\s*\"ESTIMATED_EARNINGS\":\\s*\\{\\s*\"microsValue\":\\s*\"(?<revenueMicros>\\d+)\"\\s*\\}\\s*\\}\\s*\\}"}],"url":"https://admob.googleapis.com/v1/accounts/"#,
    br#"/networkReport:generate"}"#,
];

const ADMOB_SIGNATURE_HEX: &str = "b7695d7a14d6de5fb0d1ebb2a0858e8f773247dca9e76b87c1482e9a8fe250996d9ca44151a1cc24001f62a8d568a0d218e573a03fb19a7ad638b3ea024045ce";
const ADMOB_RECOVERY_ID: u32 = 0;
const ADMOB_REVENUE_MICROS: &str = "12345678";
/// The AdSense nullifier for the fixture's publisher and window, as it has always been.
///
/// Pinned against a literal rather than recomputed, because advances already on chain are
/// keyed on exactly these bytes. Independently derived in Python —
/// `sha256` over each of `pub_id`, `window_start`, `window_end` length-prefixed with four
/// big-endian bytes — so this is not the contract agreeing with itself.
const ADSENSE_NULLIFIER: [u8; 32] = [
    0x31, 0x40, 0xb7, 0xa0, 0x1c, 0x30, 0x6d, 0x98, 0xcf, 0xed, 0x42, 0xae, 0x54, 0x09, 0x28, 0x56,
    0xf3, 0x88, 0x08, 0xa6, 0x9e, 0x15, 0xef, 0x94, 0xce, 0x26, 0xd5, 0x7a, 0x73, 0x4b, 0xa3, 0x1a,
];

const ADMOB_PROVIDER_HASH: &str =
    "0xcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcd";

struct Fx {
    env: Env,
    client: AdvanceContractClient<'static>,
    borrower: Address,
}

/// Both templates pinned, and the claim owner pinned to the app.
fn fx() -> Fx {
    let env = Env::default();
    env.mock_all_auths();
    env.ledger().set_timestamp(TIMESTAMP_S + 10);

    let verifier = env.register(MockVerifier, ());
    let id = env.register(
        AdvanceContract,
        (Address::generate(&env), verifier, Address::generate(&env)),
    );
    let client = AdvanceContractClient::new(&env, &id);

    let mut adsense = Vec::new(&env);
    for p in TEMPLATE.iter() {
        adsense.push_back(Bytes::from_slice(&env, p));
    }
    client.set_claim_template(
        &Source::AdSense,
        &adsense,
        &Bytes::from_slice(&env, PROVIDER_HASH.as_bytes()),
    );

    let mut admob = Vec::new(&env);
    for p in ADMOB_TEMPLATE.iter() {
        admob.push_back(Bytes::from_slice(&env, p));
    }
    client.set_claim_template(
        &Source::AdMob,
        &admob,
        &Bytes::from_slice(&env, ADMOB_PROVIDER_HASH.as_bytes()),
    );

    client.set_claim_owner(&Bytes::from_slice(&env, APP_OWNER.as_bytes()));

    let borrower = Address::from_string(&String::from_str(&env, BORROWER));
    Fx {
        env,
        client,
        borrower,
    }
}

fn verify_admob(f: &Fx, source: Source) -> Result<VerifiedClaim, Error> {
    match f.client.try_verify_claim(
        &source,
        &f.borrower,
        &String::from_str(&f.env, ADMOB_REVENUE_MICROS),
        &String::from_str(&f.env, PUB_ID),
        &String::from_str(&f.env, WINDOW_START),
        &String::from_str(&f.env, WINDOW_END),
        &TIMESTAMP_S,
        &EPOCH,
        &signature_from(&f.env, ADMOB_SIGNATURE_HEX),
        &ADMOB_RECOVERY_ID,
    ) {
        Ok(Ok(claim)) => Ok(claim),
        Err(Ok(e)) => Err(e),
        other => panic!("unexpected host-level result: {other:?}"),
    }
}

#[test]
fn an_admob_claim_verifies_against_its_own_template() {
    let f = fx();
    let claim = verify_admob(&f, Source::AdMob).expect("the signed AdMob fixture must verify");
    assert_eq!(claim.borrower, f.borrower);
    assert_eq!(
        claim.revenue_usd,
        String::from_str(&f.env, ADMOB_REVENUE_MICROS)
    );
    assert_eq!(claim.pub_id, String::from_str(&f.env, PUB_ID));
}

#[test]
fn an_admob_claim_cannot_be_checked_against_the_adsense_template() {
    // The template pins the host. An AdMob claim rebuilt against the AdSense template
    // hashes a request to adsense.googleapis.com, so the identifier differs and the
    // signature recovers to nobody. This is the property that makes a second source safe
    // to add: the caller's `source` argument cannot choose the host, only the template can.
    let f = fx();
    assert_eq!(
        verify_admob(&f, Source::AdSense),
        Err(Error::VerifierRejected)
    );
}

#[test]
fn an_adsense_claim_cannot_be_checked_against_the_admob_template() {
    let f = fx();
    let out = f.client.try_verify_claim(
        &Source::AdMob,
        &f.borrower,
        &String::from_str(&f.env, REVENUE),
        &String::from_str(&f.env, PUB_ID),
        &String::from_str(&f.env, WINDOW_START),
        &String::from_str(&f.env, WINDOW_END),
        &TIMESTAMP_S,
        &EPOCH,
        &crate::test_claim::signature(&f.env),
        &crate::test_claim::RECOVERY_ID,
    );
    assert_eq!(out, Err(Ok(Error::VerifierRejected)));
}

#[test]
fn an_unpinned_source_refuses_rather_than_falling_back_to_adsense() {
    // AdSense falls back to the pre-#94 singleton keys so a contract pinned before
    // sources existed keeps working. Nothing else falls back to anything.
    let env = Env::default();
    env.mock_all_auths();
    let id = env.register(
        AdvanceContract,
        (
            Address::generate(&env),
            env.register(MockVerifier, ()),
            Address::generate(&env),
        ),
    );
    let client = AdvanceContractClient::new(&env, &id);
    let mut adsense = Vec::new(&env);
    for p in TEMPLATE.iter() {
        adsense.push_back(Bytes::from_slice(&env, p));
    }
    client.set_claim_template(
        &Source::AdSense,
        &adsense,
        &Bytes::from_slice(&env, PROVIDER_HASH.as_bytes()),
    );
    client.set_claim_owner(&Bytes::from_slice(&env, APP_OWNER.as_bytes()));

    assert!(client.claim_template_for(&Source::AdSense).is_some());
    assert!(client.claim_template_for(&Source::AdMob).is_none());

    let out = client.try_verify_claim(
        &Source::AdMob,
        &Address::from_string(&String::from_str(&env, BORROWER)),
        &String::from_str(&env, ADMOB_REVENUE_MICROS),
        &String::from_str(&env, PUB_ID),
        &String::from_str(&env, WINDOW_START),
        &String::from_str(&env, WINDOW_END),
        &TIMESTAMP_S,
        &EPOCH,
        &signature_from(&env, ADMOB_SIGNATURE_HEX),
        &ADMOB_RECOVERY_ID,
    );
    assert_eq!(out, Err(Ok(Error::TemplateNotSet)));
}

#[test]
fn pinning_admob_leaves_the_adsense_template_untouched() {
    let f = fx();
    let adsense = f
        .client
        .claim_template_for(&Source::AdSense)
        .expect("adsense stays pinned");
    assert_eq!(
        adsense.get(0).unwrap(),
        Bytes::from_slice(&f.env, TEMPLATE[0])
    );
    // And the argument-free getter still answers for AdSense, so anything reading it
    // from before #94 keeps working.
    assert_eq!(f.client.claim_template(), Some(adsense));
}

#[test]
fn the_adsense_nullifier_bytes_did_not_change() {
    // Pinned against a literal, because advances already on chain are keyed on exactly
    // these bytes. If this test ever has to be updated, those records are orphaned.
    let f = fx();
    let n = f.client.nullifier_for(
        &Source::AdSense,
        &String::from_str(&f.env, PUB_ID),
        &String::from_str(&f.env, WINDOW_START),
        &String::from_str(&f.env, WINDOW_END),
    );
    assert_eq!(n.to_array(), ADSENSE_NULLIFIER);
}

#[test]
fn admob_and_adsense_do_not_share_a_nullifier() {
    // One Google account's AdSense and AdMob publisher ids are the same `pub-` id —
    // confirmed on a real account in #93. Untagged, an AdMob proof would spend the
    // AdSense nullifier for the same window, or be blocked by it. They are different
    // money and each should be borrowable once.
    let f = fx();
    let adsense = f.client.nullifier_for(
        &Source::AdSense,
        &String::from_str(&f.env, PUB_ID),
        &String::from_str(&f.env, WINDOW_START),
        &String::from_str(&f.env, WINDOW_END),
    );
    let admob = f.client.nullifier_for(
        &Source::AdMob,
        &String::from_str(&f.env, PUB_ID),
        &String::from_str(&f.env, WINDOW_START),
        &String::from_str(&f.env, WINDOW_END),
    );
    assert_ne!(adsense, admob);
}

#[test]
fn micros_truncate_to_cents_and_never_round_up() {
    let env = Env::default();
    let cents = |s: &str| sizing::parse_micros_cents(&env, &String::from_str(&env, s));

    assert_eq!(cents("12345678"), Some(1234)); // $12.345678 -> 1234c, not 1235
    assert_eq!(cents("1239999"), Some(123)); // $1.239999  -> 123c, not 124
    assert_eq!(cents("10000"), Some(1)); // one cent exactly
    assert_eq!(cents("9999"), Some(0)); // just under a cent
    assert_eq!(cents("0"), Some(0));

    // Not a plain non-negative integer: refused rather than coerced. A micros field has
    // no fractional part, so accepting a '.' would mean accepting a figure in a unit we
    // were not given.
    for bad in ["12.34", "-1", "12 34", "", "1e6", "0x10"] {
        assert_eq!(cents(bad), None, "{bad}");
    }
}

#[test]
fn dollars_and_micros_are_never_interchangeable() {
    // The asymmetry that is the whole reason the context key differs per source.
    // `12345678` read as dollars is $12,345,678 and sizes to the cap, silently.
    let env = Env::default();
    let as_micros = sizing::parse_micros_cents(&env, &String::from_str(&env, "12345678")).unwrap();
    let as_dollars = sizing::parse_usd_cents(&env, &String::from_str(&env, "12345678")).unwrap();
    assert_eq!(as_micros, 1234);
    assert_eq!(as_dollars, 1_234_567_800);
    assert_eq!(
        sizing::advance_stroops(as_dollars),
        Some(sizing::ADVANCE_CAP_STROOPS),
        "micros read as dollars returns the cap rather than erroring, which is why the \
         key names the unit inside the signed context"
    );
}

#[test]
fn an_advance_with_no_recorded_source_reads_as_adsense() {
    // `DataKey::AdvanceSource` is written only for a source that is not AdSense, so
    // absent is the answer for every advance recorded before #94 existed. Those entries
    // are debts; they must read correctly, not merely decode.
    let f = fx();
    let nullifier = f.client.nullifier_for(
        &Source::AdSense,
        &String::from_str(&f.env, PUB_ID),
        &String::from_str(&f.env, WINDOW_START),
        &String::from_str(&f.env, WINDOW_END),
    );
    assert_eq!(f.client.advance_source(&nullifier), Source::AdSense);
    assert_eq!(f.client.advance(&nullifier), None);
}
